"""Complete whole trout and cold mutton platters from full primary sources."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

r=add(40,'Lachsforelle in Majonessauce — Cold Trout with Egg-Yolk Coating',8,180,'A gently poached whole trout is served cold beneath a thick coating of sieved hard-boiled yolks, pasteurized yolks, olive oil and savory jelly.',[
 I('fish',2000,'g','whole salmon trout, gutted, scaled and gills removed by the fishmonger, head retained','Use a similar-sized whole rainbow trout; cook to the same internal temperature.'),water(2500,'poachwater'),I('wine',250,'ml','dry white wine','Use the same volume of unsalted fish stock; the flavor will be less acidic.'),I('poachvinegar',50,'ml','white wine vinegar','Use the same volume of cider vinegar.'),I('poachlemon',1,'','lemon, thinly sliced','Use one small lime per lemon for a different flavor.'),I('bay',2,'','dried bay leaves','Omit if unavailable.'),I('cloves',3,'','whole cloves','Omit for a milder poaching broth.'),I('peppercorns',1,'tsp','whole black peppercorns','Use the same amount of white peppercorns.'),I('fishsalt',4,'g','fine salt for the fish','Reduce or omit.'),I('brothsalt',10,'g','salt for the poaching broth','Reduce or omit.'),eggs(8),water(2000),yolks(8),oil(30),I('jellystock',24,'ml','unsalted clear fish stock','Use the same volume of clear unsalted vegetable stock.'),I('bloomwater',6,'ml','cold drinking water for gelatin','Use the same volume of cold clear stock.'),I('gelatin',1,'g','unflavored powdered gelatin, approximately 200 Bloom','Use the same weight of fish gelatin with a similar setting strength; agar requires a different formula.')],[
 'Use a fish kettle or deep roasting pan with a lifting rack large enough for the whole fish. Add {{poachwater}}, {{wine}}, {{poachvinegar}}, {{poachlemon}}, {{bay}}, {{cloves}}, {{peppercorns}} and {{brothsalt}}. Bring to a gentle simmer for 10 minutes.',
 'Pat {{fish}} dry and rub its surface and cavity with {{fishsalt}}. Lower it on the rack into the broth. Add extra hot drinking water only if needed to cover. Keep at a bare simmer, without a rolling boil, for about 25–35 minutes. The thickest flesh must reach 63°C (145°F); use the temperature rather than the time alone.',
 'Lift out on the rack and drain. Transfer carefully to a clean shallow platter that fits in the refrigerator. Once the strong steam subsides, cover loosely and refrigerate promptly, within 2 hours of cooking, until thoroughly cold, allowing about 1–2 hours. Do not leave the whole fish on the counter to cool completely.',
 *boil(),
 'Separate the firm cooked yolks and press them through a fine sieve into a clean bowl. Refrigerate the cooked whites separately for another dish within 2 days. Whisk {{yolks}} into the sieved yolks until smooth.',
 'Sprinkle {{gelatin}} over {{bloomwater}} in a small heatproof bowl and leave for 5 minutes. Add {{jellystock}} and stand the bowl over gently simmering water, stirring just until the gelatin dissolves. Remove from heat and cool until barely lukewarm but still liquid.',
 'Beat half the liquid jelly into the yolk mixture. Measure {{oil}} and whisk it in drop by drop until incorporated, then whisk in the remaining jelly. Set the bowl over cold water and stir until the coating is thick and spreadable; do not let it set solid. If it firms too soon, briefly stand the bowl in lukewarm water and stir to soften.',
 'Spread the coating over the cold fish, leaving the head uncovered as in the original. Refrigerate for about 20 minutes to firm the surface. Serve cold, lifting the flesh from the backbone in portions and checking carefully for pin bones; the head and bones are not eaten.',END],
 'The original recipe 476 specifies eight hard-boiled yolks, eight fresh yolks and two tablespoons olive oil. Those proportions are retained, with pasteurized yolks replacing raw untreated yolks. A modern 2 kg fish, measured aromatic broth and approximately 30 ml of freshly made jelly are supplied because the source gives no fish weight, broth quantities or jelly formula. The first unspecified spoon of jelly and later tablespoon are represented by equal halves of this modern jelly batch, not asserted as verified historical conversions. Brief whisking and controlled chilling replace the source’s two and a half hours of beating. A whole fish requires a suitably sized pan and refrigerator space. Eight meal portions and timing are estimates; the coating texture has not been kitchen-tested.');finish(r)

r=add(51,'W. H. H.’s Cold Mutton Platter with Lime Mayonnaise',8,285,'Thin slices of cold roast leg of mutton are dressed with lime mayonnaise and arranged with lettuce, savory jelly, pickles, olives, anchovies and hard-boiled yolks.',[
 I('mutton',1500,'g','boneless leg of mutton, suitable for roasting, tied into an even joint by the butcher','Use the same weight of boneless leg of lamb for more tender slices; check the same safe internal temperature.'),I('roastsalt',5,'g','fine salt for the roast','Reduce or omit.'),I('roastoil',15,'ml','olive oil for the roast','Use the same volume of sunflower oil.'),yolks(3),oil(284),I('lime',40,'ml','fresh lime juice','Use the same volume of lemon juice.'),salt(1),I('tarragonvinegar',2.5,'ml','tarragon vinegar','Use the same volume of white wine vinegar.'),pepper(.125),I('lettuce',150,'g','lettuce leaves, washed and thoroughly dried','Use the same weight of romaine hearts.'),I('aspicstock',120,'ml','clear unsalted beef stock','Use the same volume of clear unsalted vegetable stock.'),I('aspicwater',15,'ml','cold drinking water for gelatin','Use the same volume of cold clear stock.'),I('aspicgelatin',3,'g','unflavored powdered gelatin, approximately 200 Bloom','Use the same weight of fish gelatin of similar strength; agar needs a different method.'),I('gherkins',40,'g','drained pickled gherkins, sliced','Use the same weight of pickled cucumber.'),I('olives',40,'g','drained pitted green olives','Use the same weight of pitted black olives.'),I('capers',15,'g','drained capers','Use the same weight of finely chopped pickled gherkins.'),I('anchovies',20,'g','ready-to-eat oil-packed anchovy fillets, drained','Omit, or add the same weight of olives for a fish-free garnish.'),I('butter',20,'g','unsalted butter, softened, for small butter balls','Omit if preferred; this is a garnish rather than part of the mayonnaise.'),eggs(2),water(750)],[
 'Heat the oven to 165°C (330°F). Pat {{mutton}} dry and rub with {{roastoil}} and {{roastsalt}}. Place on a rack in a roasting tin. Roast for about 90–120 minutes, until the center reaches at least 63°C (145°F). Allow longer if needed; thickness and the age of the animal affect timing and tenderness.',
 'Rest the roast for 20 minutes, including at least 3 minutes before any cutting. Remove the string. Slice thinly across the grain and spread the slices in shallow containers with the collected cooked juices. Refrigerate promptly, within 2 hours of cooking, until fully cold, allowing about 2 hours. Do not leave a whole joint on the counter until cold.',
 'While the meat cooks, sprinkle {{aspicgelatin}} over {{aspicwater}} and leave for 5 minutes. Warm {{aspicstock}} just below boiling. Stir in the bloomed gelatin until dissolved. Pour into a shallow dish, cover and refrigerate for about 2 hours until set. Cut or break the jelly into small pieces.',
 *boil(),
 'Separate the hard-boiled yolks, keeping them whole for garnish. Refrigerate them until assembly; reserve the cooked whites in a covered container for another dish within 2 days. Roll {{butter}} into pea-sized balls with clean chilled hands or two small spoons, then refrigerate until firm.',
 'For the sauce, whisk {{yolks}}, {{lime}} and {{salt}} in a clean bowl set on a damp towel. Measure {{oil}} into a jug. Whisk it in drop by drop at first, then in a very thin stream as the sauce thickens. Stop pouring if oil pools and whisk until it blends in. Cover and refrigerate while arranging the platter.',
 'Arrange the cold mutton on a chilled platter and season with {{tarragonvinegar}} and {{pepper}}. Arrange {{lettuce}} around and among the meat. Add the prepared jelly, butter balls and whole cooked yolks, then garnish with {{gherkins}}, {{olives}}, {{capers}} and {{anchovies}}. Spoon the cold lime mayonnaise over the meat just before serving.',END],
 'The full original paragraph recommends juicy slices of cold leg of mutton; that central ingredient was missing from the extracted entry. This adaptation supplies a complete roasting and chilling method, measured meat and garnish quantities and eight servings. The original three large yolks and teaspoon salt are retained. Half a pint of oil is represented by a modern Imperial half-pint rounded to 284 ml; the juice of two limes is standardized to a working 40 ml rather than a universal fruit conversion. The source permits garnishes “as you like”; this version chooses its plain yellow butter balls and includes the named jelly, pickles, olives, capers, anchovies and cooked yolks. Older mutton can be firmer than lamb even at a safe temperature; ask the butcher for a roasting-suitable leg and slice thinly. Total time includes overlapping garnish preparation, roasting, resting and refrigeration.');finish(r)

assert len(newids)==2
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full primary source restored; complete measured cold platter with cooking, sauce, garnish and chilling supplied','repair-batch-030.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),totalOverrides=len(records),totalAliases=len(aliases))))
